package com.etpms;
import com.etpms.dao.TaskDAO;import com.etpms.model.User;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet(urlPatterns={"/dashboard","/tasks","/employees"}) public class DashboardServlet extends HttpServlet {private final TaskDAO dao=new TaskDAO();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");try{q.setAttribute("stats",dao.stats(u));q.setAttribute("tasks",dao.list(u));if(!"EMPLOYEE".equals(u.role))q.setAttribute("employees",dao.employees());q.setAttribute("page",q.getServletPath());q.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");try{if("create".equals(q.getParameter("action"))&&java.util.Set.of("ADMIN","MANAGER").contains(u.role)){String title=q.getParameter("title"),priority=q.getParameter("priority"),start=q.getParameter("startDate"),due=q.getParameter("dueDate");if(title==null||title.isBlank()||title.length()>180||!java.util.Set.of("LOW","MEDIUM","HIGH","URGENT").contains(priority)||start==null||due==null||java.time.LocalDate.parse(due).isBefore(java.time.LocalDate.parse(start)))throw new IllegalArgumentException("Enter valid task details and dates.");dao.create(title.trim(),q.getParameter("description"),priority,start,due,u.id,Long.parseLong(q.getParameter("assignee")),u.role);q.getSession().setAttribute("notice","Task created successfully.");}else if("status".equals(q.getParameter("action"))){dao.updateStatus(Long.parseLong(q.getParameter("taskId")),q.getParameter("status"),u.id,u.role);q.getSession().setAttribute("notice","Task status updated.");}p.sendRedirect(q.getContextPath()+"/dashboard");}catch(Exception e){q.getSession().setAttribute("error",e.getMessage());p.sendRedirect(q.getContextPath()+"/dashboard");}}}
